/* Minimal htmx-compatible subset for SimpleDraw. */
(function () {
  function resolveTarget(element) {
    const selector = element.getAttribute("hx-target");
    return selector ? document.querySelector(selector) : element;
  }

  function request(element, event) {
    const url = element.getAttribute("hx-get");
    if (!url) return;

    if (event && typeof event.preventDefault === "function") {
      event.preventDefault();
    }

    fetch(url, { headers: { "HX-Request": "true" } })
      .then((response) => response.text())
      .then((html) => {
        const target = resolveTarget(element);
        if (!target) return;

        target.innerHTML = html;
        boot(target);
        document.body.dispatchEvent(new CustomEvent("htmx:afterSwap", {
          detail: { target: target, elt: element },
        }));
      });
  }

  function boot(root) {
    root.querySelectorAll("[hx-get]").forEach((element) => {
      if (element.dataset.htmxBound) return;
      element.dataset.htmxBound = "1";

      if ((element.getAttribute("hx-trigger") || "").includes("load")) {
        request(element);
      }

      element.addEventListener("click", (event) => request(element, event));
    });
  }

  document.addEventListener("DOMContentLoaded", () => boot(document));
})();
